function damagePlayer(dmg,x=player.x,y=player.y){if(player.invuln>0||player.dead)return;player.hp=Math.max(0,player.hp-dmg);player.flash=.3;shake=Math.max(shake,7);for(let i=0;i<12;i++)spawnParticle(x,y,'dust');sound('hurt');if(player.hp<=0){player.dead=true;save.deaths++;persist();setTimeout(()=>{if(state==='playing')endGame(false)},850)}updateHud()}
function resolveBossAttack(a){if(a.hit)return;a.hit=true;let dx=player.x-a.tx,dy=player.y-a.ty,dist=Math.hypot(dx,dy);if(a.type==='melee'&&Math.hypot(player.x-boss.x,player.y-boss.y)<125)damagePlayer(28);else if(a.type==='wave'&&Math.hypot(player.x-boss.x,player.y-boss.y)<250)damagePlayer(22);else if(a.type==='mark'&&dist<55)damagePlayer(38,a.tx,a.ty);else if(a.type==='sweep'){let d=Math.hypot(player.x-boss.x,player.y-boss.y),ang=Math.atan2(player.y-boss.y,player.x-boss.x),dif=Math.atan2(Math.sin(ang-a.dir),Math.cos(ang-a.dir));if(d<205&&Math.abs(dif)<1.12)damagePlayer(32)}else if(a.type==='roar'&&Math.hypot(player.x-boss.x,player.y-boss.y)<195)damagePlayer(18);}
function update(dt){ambientTime+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('on')}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(const p of embers){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0||Math.hypot(p.x,p.y)>arenaR/scale)Object.assign(p,makeEmber())}for(const p of decos){p.age+=dt}
 if(state!=='playing')return;elapsed+=dt;boss.anim+=dt;if(boss.hurt>0)boss.hurt-=dt;if(player.flash>0)player.flash-=dt;if(player.attack>0)player.attack-=dt;if(player.dodgeCd>0)player.dodgeCd-=dt;if(player.invuln>0)player.invuln-=dt;player.walk+=dt*8;
 let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touchVec.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touchVec.y;let len=Math.hypot(dx,dy);if(len>1){dx/=len;dy/=len}if(player.dodge&&player.dodge.t>0){dx=player.dodge.x*3.1;dy=player.dodge.y*3.1;player.dodge.t-=dt}else{dx*=185;dy*=185}if(Math.hypot(dx,dy)>.1){player.x+=dx*dt;player.y+=dy*dt;if(!player.dodge){player.dir=Math.atan2(dy,dx);player.faceX=Math.cos(player.dir);player.faceY=Math.sin(player.dir)}}let bound=arenaR/scale-24,pr=Math.hypot(player.x,player.y);if(pr>bound){player.x=player.x/pr*bound;player.y=player.y/pr*bound}
 if(pointer.active&&!player.dodge){let pt=screenWorld(pointer.x,pointer.y);if(Math.hypot(pt.x-player.x,pt.y-player.y)>20){player.dir=Math.atan2(pt.y-player.y,pt.x-player.x);player.faceX=Math.cos(player.dir);player.faceY=Math.sin(player.dir)}}
 let phase=boss.hp/boss.max<=.25?3:boss.hp/boss.max<=.5?2:boss.hp/boss.max<=.75?1:0;if(phase!==boss.phase){boss.phase=phase;showToast(['THE WARDEN STIRS','THE SEAL IS CRACKING','ITS EMBERS BURN BRIGHTER','RAGE OF THE CINDER KING'][phase]);sound('phase')}
 boss.nextAttack-=dt;if(boss.nextAttack<=0&&!boss.attack){bossAttack();let intervals=[2.5,2.1,1.8,1.48];boss.nextAttack=intervals[boss.phase]+Math.random()*.55}
 if(boss.attack){let a=boss.attack;a.t+=dt;if(a.t>=a.delay&&!a.hit){resolveBossAttack(a);shake=Math.max(shake,a.type==='wave'?9:5);if(a.type==='wave'){for(let i=0;i<32;i++){let an=i*Math.PI/16;spawnParticle(boss.x+Math.cos(an)*65,boss.y+Math.sin(an)*65,'dust')}}sound(a.type==='roar'?'roar':'impact')}if(a.t>a.delay+.55)boss.attack=null}
 for(const a of attackFX)a.life-=dt;attackFX=attackFX.filter(a=>a.life>0);shake=Math.max(0,shake-dt*18);updateHud();if(boss.hp<=0&&state==='playing')endGame(true);
}
function endGame(victory){if(state!=='playing')return;state=victory?'victory':'defeat';$('#hud').style.display='none';if(victory){let active=player.damage>=1000;if(active){save.wins++;save.bosses++;let old=save.rank;if(save.rank<6&&save.wins>=thresholds[save.rank+1])save.rank++;persist();setOverlay(`<div class="eyebrow">The forest remembers</div><h1 class="title">VICTORY</h1><div class="subtitle">THE CINDER WARDEN HAS FALLEN</div><p class="description">The last embers fade beneath a blood-red dawn. Your name is etched into the old stone.</p><div class="rank-line">${rankTitle(old)} ${old<save.rank?'→ '+rankTitle(save.rank):'· SURVIVED'}</div><div class="result-grid"><div><b>${player.damage.toLocaleString()}</b><span>DAMAGE DEALT</span></div><div><b>${player.hits}</b><span>HITS LANDED</span></div><div><b>${fmt(elapsed)}</b><span>BATTLE TIME</span></div></div><div class="small">${save.rank<6?`${Math.max(0,thresholds[save.rank+1]-save.wins)} SURVIVED VICTORY${thresholds[save.rank+1]-save.wins===1?'':'IES'} TO NEXT RANK`:'MAXIMUM RANK ATTAINED'}</div><button class="button" onclick="window.playAgain()">RETURN TO THE ARENA</button>`)}else{persist();setOverlay(`<div class="eyebrow">The ash settles</div><h1 class="title">VICTORY</h1><div class="subtitle">THE WARDEN HAS FALLEN</div><p class="description">You survived, but the ancient rite demands a warrior who has helped turn the tide. Deal at least 1,000 damage in a battle to claim your rank progression.</p><div class="result-grid"><div><b>${player.damage.toLocaleString()}</b><span>DAMAGE DEALT</span></div><div><b>${player.hits}</b><span>HITS LANDED</span></div><div><b>${fmt(elapsed)}</b><span>BATTLE TIME</span></div></div><button class="button" onclick="window.playAgain()">FIGHT AGAIN</button>`)}}else{persist();setOverlay(`<div class="eyebrow">Ash to ash</div><h1 class="title">DEFEAT</h1><div class="subtitle">THE WARDEN CLAIMS THE ARENA</div><p class="description">Your blade falls silent. The forest will wait for another dawn.</p><div class="result-grid"><div><b>${player.damage.toLocaleString()}</b><span>DAMAGE DEALT</span></div><div><b>${player.hits}</b><span>HITS LANDED</span></div><div><b>${fmt(elapsed)}</b><span>BATTLE TIME</span></div></div><div class="small">NO VICTORY PROGRESSION · RANKS NEVER DECREASE</div><button class="button" onclick="window.playAgain()">RISE AGAIN</button>`)}sound(victory?'victory':'defeat')}

