 for(let ring=0;ring<7;ring++){ctx.beginPath();ctx.arc(cx,cy,r*(.19+ring*.115),0,Math.PI*2);ctx.strokeStyle=ring%2?'#8b79621a':'#17151240';ctx.lineWidth=1.5;ctx.stroke()}
 for(let i=0;i<108;i++){let a=(i*2.399),rr=Math.sqrt((i*0.618)%1)*r*.94,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr,sz=2+(i*7%13);ctx.fillStyle=i%3?'#d8c6a009':'#0807061a';ctx.beginPath();ctx.ellipse(x,y,sz*1.8,sz*.65,a,0,6.28);ctx.fill()}
