 // old ring markings
 ctx.strokeStyle='#a18a6b22';ctx.lineWidth=2;for(let i=0;i<24;i++){let a=i*Math.PI/12;ctx.beginPath();ctx.moveTo(cx+Math.cos(a)*r*.78,cy+Math.sin(a)*r*.78);ctx.lineTo(cx+Math.cos(a)*r*.83,cy+Math.sin(a)*r*.83);ctx.stroke()}
 ctx.restore();ctx.strokeStyle='#b295704d';ctx.lineWidth=3;pathCircle(cx,cy,r-2);ctx.stroke();ctx.strokeStyle='#0c0b09';ctx.lineWidth=6;pathCircle(cx,cy,r+5);ctx.stroke();
 // soot smears and glowing fissures
 for(let i=0;i<13;i++){let a=i*2.4,r0=r*(.67+(i%3)*.07),x=cx+Math.cos(a)*r0,y=cy+Math.sin(a)*r0;ctx.fillStyle='#17131042';ctx.beginPath();ctx.ellipse(x,y,22,10,a,0,6.28);ctx.fill()}
