function drawParticles(){for(const q of particles){let p=screenPt(q.x,q.y);ctx.globalAlpha=Math.max(0,Math.min(1,q.life/(q.max||.5)));ctx.fillStyle=q.type==='spark'?'#ffbf68':q.type==='dust'?'#b5a28d':'#d0c0a9';ctx.shadowColor=q.type==='spark'?'#ff6a30':'transparent';ctx.shadowBlur=q.type==='spark'?8:0;ctx.beginPath();ctx.arc(p.x,p.y,q.size*scale,0,6.28);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;for(const e of embers){let p=screenPt(e.x,e.y);ctx.globalAlpha=e.alpha*(.55+.45*Math.sin(ambientTime*7+e.life));ctx.fillStyle='#ff9b54';ctx.shadowColor='#ef4e2c';ctx.shadowBlur=9;ctx.beginPath();ctx.arc(p.x,p.y,e.size*scale,0,6.28);ctx.fill()}ctx.globalAlpha=1;ctx.shadowBlur=0;for(const a of attackFX){let p=screenPt(a.x,a.y),al=a.life/a.max;ctx.globalAlpha=al;ctx.strokeStyle=a.type==='hit'?'#ffb35e':'#dfd5bb';ctx.lineWidth=a.type==='hit'?3:2;ctx.beginPath();ctx.arc(p.x,p.y,(a.type==='hit'?11:28)*(1-al*.4)*scale,a.dir-1.6,a.dir+1.6);ctx.stroke()}ctx.globalAlpha=1}
function drawVignette(){let g=ctx.createRadialGradient(cx,cy,arenaR*.52,cx,cy,Math.max(W,H)*.75);g.addColorStop(0,'rgba(0,0,0,0)');g.addColorStop(.7,'rgba(7,6,6,.12)');g.addColorStop(1,'rgba(0,0,0,.7)');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let haze=ctx.createRadialGradient(cx,cy,arenaR*.6,cx,cy,arenaR*1.1);haze.addColorStop(0,'rgba(255,111,62,0)');haze.addColorStop(1,'rgba(126,49,32,.08)');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H)}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawForest();drawArena();drawProps();drawTelegraph();if(boss)drawBoss();if(player&&!player.dead)drawPlayer();if(player&&player.dead){let p=screenPt(player.x,player.y);ctx.fillStyle='#0b0a09b5';ctx.beginPath();ctx.ellipse(p.x,p.y,14*scale,8*scale,0,0,6.28);ctx.fill();ctx.strokeStyle='#a8644d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x-6,p.y-4);ctx.lineTo(p.x+6,p.y+4);ctx.moveTo(p.x+6,p.y-4);ctx.lineTo(p.x-6,p.y+4);ctx.stroke()}drawParticles();ctx.restore();drawVignette();if(!state||state==='menu'){ctx.fillStyle='#e49a5e';ctx.globalAlpha=.6+Math.sin(ambientTime*2)*.2;ctx.beginPath();ctx.arc(W*.5,H*.77,2,0,6.28);ctx.fill();ctx.globalAlpha=1}}
let musicVol=.13,sfxVol=.35,musicTimer=0,musicStep=0;
function audio(){if(!audioCtx){try{audioCtx=new (window.AudioContext||window.webkitAudioContext)()}catch(e){return}}if(audioCtx.state==='suspended')audioCtx.resume()}
function tone(freq,dur,type='sine',vol=.08,det=0){if(!musicOn&&type==='music')return;audio();if(!audioCtx)return;let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;o.detune.value=det;g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(Math.max(.0002,vol*(type==='music'?musicVol:sfxVol)),audioCtx.currentTime+.025);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur+.03)}
function sound(k){if(k==='slash'){tone(510,.12,'triangle',.13,180);tone(720,.09,'sine',.06,-120)}else if(k==='dodge')tone(250,.18,'triangle',.09,-100);else if(k==='warning'){tone(92,.4,'sine',.13);tone(184,.32,'triangle',.08)}else if(k==='impact'){tone(56,.38,'sawtooth',.16);tone(120,.23,'triangle',.1)}else if(k==='roar'){tone(75,.7,'sawtooth',.13,-40);tone(110,.6,'sine',.12,45)}else if(k==='hurt')tone(130,.2,'triangle',.1);else if(k==='phase'){tone(220,.45,'sine',.1);tone(330,.55,'triangle',.09)}else if(k==='victory'){[392,494,587,784].forEach((n,i)=>setTimeout(()=>tone(n,.8,'sine',.13),i*160))}else if(k==='defeat'){tone(110,1,'sawtooth',.12,-80)}}
function musicUpdate(dt){if(!musicOn||state==='menu'||state==='victory'||state==='defeat')return;musicTimer-=dt;if(musicTimer<=0){musicTimer=.72;let phase=boss?boss.phase:0,scaleNotes=[146.83,174.61,220,261.63,293.66,349.23,392];let base=scaleNotes[(musicStep*2+phase*2)%scaleNotes.length];tone(base,.65,'sine',.22,'music');if(musicStep%4===0)tone(base/2,.7,'triangle',.22,'music');if(musicStep%2===0)tone(base*1.5,.36,'sine',.09,'music');if(musicStep%4===0){tone(54,.16,'sine',.25,'music');}musicStep++}}

