 function musicUpdate(dt){if(!musicOn||state==='menu'||state==='victory'||state==='defeat')return;musicTimer-=dt;if(musicTimer<=0){musicTimer=.72;let phase=boss?boss.phase:0,scaleNotes=[146.83,174.61,220,261.63,293.66,349.23,392];let base=scaleNotes[(musicStep*2+phase*2)%scaleNotes.length];tone(base,.65,'sine',.22,0,'music');if(musicStep%4===0)tone(base/2,.7,'triangle',.22,0,'music');if(musicStep%2===0)tone(base*1.5,.36,'sine',.09,0,'music');if(musicStep%4===0){tone(54,.16,'sine',.25,0,'music');}musicStep++}}
+function menu(){boss={x:0,y:-15,r:66,hp:50000,max:50000,phase:0,attack:null,nextAttack:2,anim:0,hurt:0};player=null;$('#hud').style.display='none';$('#touch').style.display='none';setOverlay(`<div class="eyebrow">A 2D co-op boss battle · local build</div><h1 class="title">THE ASHEN<br>ARENA</h1><div class="subtitle">THE CINDER WARDEN</div><p class="description">A scorched shrine. A fallen god. One blade against the last ember.<br>Survive the Warden and earn your place among the seven ranks.</p><div class="rank-line">${rankTitle()} &nbsp;·&nbsp; ${save.wins} SURVIVED VICTORIES</div><button class="button" onclick="window.playAgain()">ENTER THE ARENA</button><div class="small">WASD / ARROWS MOVE &nbsp;·&nbsp; SPACE ATTACK &nbsp;·&nbsp; SHIFT DODGE<br>Mouse aims and attacks · Touch controls supported<br><span style="color:#c9805c">LOCAL SOLO VERSION · ONLINE MULTIPLAYER NOT CONNECTED</span></div><div style="display:flex;justify-content:center;gap:22px;margin-top:18px;font-size:9px;letter-spacing:.13em;color:#9b8b79"><label>MUSIC <input id="musicVolume" type="range" min="0" max="100" value="13" style="width:75px;vertical-align:middle;accent-color:#b86a4c"></label><label>SFX <input id="sfxVolume" type="range" min="0" max="100" value="35" style="width:75px;vertical-align:middle;accent-color:#b86a4c"></label></div>`);$('#musicVolume').oninput=e=>musicVol=e.target.value/100;$('#sfxVolume').oninput=e=>sfxVol=e.target.value/100}
+window.playAgain=()=>{audio();musicOn=true;musicStep=0;musicTimer=0;startGame();$('#touch').style.display='block';tone(146,.7,'sine',.18,0,'music')};
+function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);musicUpdate(dt);if(boss&&state==='menu')boss.anim+=dt;render();requestAnimationFrame(frame)}
+addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '&&!e.repeat)beginAttack();if(k==='shift'&&!e.repeat)dodge()});addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
+canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;pointer.active=true});canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;pointer.x=e.clientX;pointer.y=e.clientY;pointer.active=true;if(e.button===2)dodge();else beginAttack()});canvas.addEventListener('contextmenu',e=>e.preventDefault());
+const stick=$('#stick'),nub=$('#nub');stick.addEventListener('pointerdown',e=>{joystick=e.pointerId;stick.setPointerCapture(joystick);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===joystick)moveStick(e)});stick.addEventListener('pointerup',e=>{if(e.pointerId===joystick){joystick=null;touchVec={x:0,y:0};nub.style.transform='translate(0,0)'}});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=39;if(d>max){dx=dx/d*max;dy=dy/d*max}touchVec={x:dx/max,y:dy/max};nub.style.transform=`translate(${dx}px,${dy}px)`}
+$('#attackBtn').addEventListener('pointerdown',e=>{e.preventDefault();beginAttack()});$('#dodgeBtn').addEventListener('pointerdown',e=>{e.preventDefault();dodge()});
+menu();requestAnimationFrame(frame);
+})();
