olor:#eb9470}.toast{position:absolute;top:105px;left:50%;transform:translateX(-50%);font:13px Cinzel,serif;letter-spacing:.12em;color:#ffc17d;text-shadow:0 2px 8px #000;opacity:0;transition:opacity .2s}.toast.on{opacity:1}.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,rgba(17,14,12,.42),rgba(7,7,7,.82));}.panel{width:min(590px,90vw);padding:40px 48px;text-align:center;border:1px solid #a87b5150;background:linear-gradient(145deg,#191612f2,#100e0df5);box-shadow:0 25px 100px #000b;position:relative}.panel:before,.panel:after{content:'';position:absolute;width:30px;height:30px;border-color:#bd8556;border-style:solid;opacity:.75}.panel:before{top:12px;left:12px;border-width:1px 0 0 1px}.panel:after{bottom:12px;right:12px;border-width:0 1px 1px 0}.eyebrow{font-size:10px;letter-spacing:.35em;color:#c88a5d;text-transform:uppercase;margin-bottom:17px}.title{font:600 clamp(38px,7vw,64px)/.95 Cinzel,serif;letter-spacing:.04em;margin:0;color:#f3e8d8;text-shadow:0 4px 24px #d4512933}.subtitle{font:14px Cinzel,serif;letter-spacing:.25em;color:#bd7755;margin-top:12px}.description{max-width:420px;margin:24px auto;color:#b6a99a;font-size:13px;line-height:1.8}.button{pointer-events:auto;border:1px solid #c88958;background:linear-gradient(180deg,#9e4c34,#6c2f25);color:#fff1df;padding:14px 30px;font:600 12px Cinzel,serif;letter-spacing:.18em;text-transform:uppercase;cursor:pointer;box-shadow:0 7px 25px #0007;transition:filter .15s,transform .15s}.button:hover{filter:brightness(1.2);transform:translateY(-1px)}.secondary{background:transparent;border-color:#786653;margin-left:8px;color:#cbbb9f}.rank-line{font:13px Cinzel,serif;color:#d5b681;margin:14px}.small{font-size:10px;line-height:1.7;color:#81776d;margin-top:20px;letter-spacing:.05em}.result-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:23px 0}.result-grid div{padding:10px;background:#ffffff08;border:1px solid #ffffff0c}.result-grid b{display:block;font:17px Cinzel,serif;color:#f0d1a3}.result-grid span{font-size:9px;letter-spacing:.12em;color:#998e80}.touch{display:none;pointer-events:none;position:absolute;inset:0}.stick{pointer-events:auto;position:absolute;bottom:36px;left:30px;width:118px;height:118px;border-radius:50%;border:1px solid #d6c6ad55;background:#1714107c;touch-action:none}.nub{position:absolute;width:42px;height:42px;border-radius:50%;left:37px;top:37px;background:#b8a48b77;border:1px solid #eddbc888}.touch-btn{pointer-events:auto;position:absolute;bottom:49px;right:30px;width:66px;height:66px;border-radius:50%;border:1px solid #d67b58;background:#672e25a8;color:#f6d8bb;font:10px Cinzel,serif;letter-spacing:.08em;touch-action:none}.touch-btn.dodge{right:107px;bottom:34px;width:52px;height:52px;border-color:#b5945d;background:#534321a8;font-size:9px}
@media(max-width:700px){.topline{top:15px;width:66vw}.top-right{right:12px;top:16px;font-size:9px}.hud-stats{left:12px;top:16px;font-size:9px}.player-card{left:12px;bottom:14px;width:155px;padding:9px}.controls{display:none}.cooldown{right:12px;bottom:15px}.touch{display:block}.panel{padding:32px 22px}.description{font-size:12px}}
