<body>
<canvas id="game"></canvas>
<div id="hud">
  <div class="hud-stats">ASHEN ARENA<br><b id="count">1 / 15</b> WARRIORS<br><b id="elapsed">00:00</b> BATTLE</div>
  <div class="topline"><div class="boss-name">THE CINDER WARDEN</div><div class="health-track"><div class="health-fill" id="bossFill"></div></div><div class="hp-label"><span id="bossHp">50,000</span> / 50,000 · <span id="bossPct">100</span>%</div></div>
  <div class="top-right">LOCAL WARRIOR <span style="color:#d7ad77">●</span><div class="phase-label" id="phase">DORMANT</div></div>
  <div class="player-card"><div class="player-name">ASHEN WARRIOR</div><div class="player-rank" id="rankName">RONIN · RANK I</div><div class="player-health"><i id="playerFill"></i></div><div class="health-text"><span>VITALITY</span><span id="playerHp">100 / 100</span></div></div>
  <div class="cooldown">DODGE <span id="dodgeLabel">READY</span></div>
  <div class="controls"><div class="keycap"><strong>WASD</strong> MOVE</div><div class="keycap"><strong>SPACE</strong> KATANA</div><div class="keycap"><strong>SHIFT</strong> DODGE</div><div class="keycap"><strong>MOUSE</strong> AIM</div></div>
  <div class="toast" id="toast"></div>
</div>
<div id="touch" class="touch"><div class="stick" id="stick"><div class="nub" id="nub"></div></div><button class="touch-btn dodge" id="dodgeBtn">DODGE</button><button class="touch-btn" id="attackBtn">SLASH</button></div>
<div class="overlay" id="overlay"><div class="panel" id="panel"></div></div>
<script>
(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), ranks=['RONIN','ASHIGARU','BUSHI','SAMURAI','HATAMOTO','SHOGUN','GOD OF WAR'], thresholds=[0,1,3,6,10,16,24];
let W=0,H=0,dpr=1,cx=0,cy=0,scale=1,arenaR=0,last=0,elapsed=0,state='menu',keys={},pointer={x:0,y:0,down:false},touchVec={x:0,y:0},joystick=null;
let save;try{save=JSON.parse(localStorage.getItem('ashenProfile'))||{};}catch(e){save={}}
save={rank:save.rank||0,wins:save.wins||0,matches:save.matches||0,bosses:save.bosses||0,damage:save.damage||0,deaths:save.deaths||0};
let player,boss,particles=[],embers=[],decos=[],attackFX=[],shake=0,toastTimer=0,ambientTime=0,musicOn=true,audioCtx=null,lastAttack=0;
function persist(){try{localStorage.setItem('ashenProfile',JSON.stringify(save))}catch(e){}}
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);cx=W/2;cy=H*.51;arenaR=Math.min(W*.41,H*.42);scale=arenaR/430;}
addEventListener('resize',resize);resize();
function profileSkin(){return save.rank||0}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('on');toastTimer=2.2}
function setOverlay(html){$('#panel').innerHTML=html;$('#overlay').style.display='flex'}
function hideOverlay(){$('#overlay').style.display='none'}
function startGame(){
 state='playing';save.matches++;persist();elapsed=0;last=performance.now();boss={x:0,y:-15,r:66,hp:50000,max:50000,phase:0,attack:null,nextAttack:2.1,anim:0,hurt:0,dead:false};
 player={x:Math.random()*40-20,y:145,hp:100,max:100,r:13,dir:Math.PI*1.5,faceX:0,faceY:-1,attack:0,dodge:0,dodgeCd:0,invuln:0,dead:false,damage:0,hits:0,walk:0,flash:0};
 particles=[];embers=[];attackFX=[];shake=0;lastAttack=0;for(let i=0;i<120;i++)particles.push(makeAsh(true));for(let i=0;i<35;i++)embers.push(makeEmber(true));
 $('#hud').style.display='block';hideOverlay();updateHud();
}
function makeAsh(initial){let a=Math.random()*Math.PI*2,r=Math.sqrt(Math.random())*.97;return{x:Math.cos(a)*arenaR*r,y:Math.sin(a)*arenaR*r,vx:(Math.random()-.5)*8,vy:-5-Math.random()*12,size:.6+Math.random()*1.7,alpha:.09+Math.random()*.2,phase:Math.random()*6.2}}
function makeEmber(initial){let a=Math.random()*Math.PI*2,r=Math.sqrt(Math.random())*.92;return{x:Math.cos(a)*arenaR*r,y:Math.sin(a)*arenaR*r,vx:(Math.random()-.5)*14,vy:-9-Math.random()*16,size:1+Math.random()*2,life:Math.random()*5,alpha:.4+Math.random()*.6}}
function rankTitle(i=save.rank){return `${ranks[i]} · RANK ${['I','II','III','IV','V','VI','VII'][i]}`}
function updateHud(){if(!boss||!player)return;$('#bossFill').style.width=Math.max(0,boss.hp/boss.max*100)+'%';$('#bossHp').textContent=Math.ceil(boss.hp).toLocaleString();$('#bossPct').textContent=Math.ceil(boss.hp/boss.max*100);$('#playerFill').style.width=Math.max(0,player.hp)+'%';$('#playerHp').textContent=`${Math.ceil(player.hp)} / 100`;$('#rankName').textContent=rankTitle();$('#elapsed').textContent=fmt(elapsed);$('#phase').textContent=['DORMANT','IGNITION','CRACKING','RAGE'][boss.phase]||'RAGE';$('#dodgeLabel').textContent=player.dodgeCd<=0?'READY':player.dodgeCd.toFixed(1)+'s'}
function fmt(t){let m=Math.floor(t/60),s=Math.floor(t%60);return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function world(x,y){return{x:cx+x*scale,y:cy+y*scale}}
function beginAttack(){if(state!=='playing'||player.dead)return;const now=performance.now()/1000;if(now-lastAttack<.31)return;lastAttack=now;player.attack=.27;let dir=player.dir;
 if(pointer.active){let p=screenWorld(pointer.x,pointer.y);let dx=p.x-player.x,dy=p.y-player.y;if(Math.hypot(dx,dy)>8){dir=Math.atan2(dy,dx);player.dir=dir;player.faceX=Math.cos(dir);player.faceY=Math.sin(dir)}}
 let reach=112,angle=Math.atan2(boss.y-player.y,boss.x-player.x),dist=Math.hypot(boss.x-player.x,boss.y-player.y);let diff=Math.atan2(Math.sin(angle-dir),Math.cos(angle-dir));
 if(dist<reach+boss.r&&Math.abs(diff)<1.17){boss.hp=Math.max(0,boss.hp-20);boss.hurt=.16;player.damage+=20;player.hits++;save.damage+=20;let p={x:boss.x+Math.cos(angle)*boss.r*.72,y:boss.y+Math.sin(angle)*boss.r*.72};for(let i=0;i<8;i++)spawnParticle(p.x,p.y,'spark');attackFX.push({x:p.x,y:p.y,dir,life:.27,max:.27,type:'hit'});if(boss.hp<=0)endGame(true)}else attackFX.push({x:player.x+Math.cos(dir)*30,y:player.y+Math.sin(dir)*30,dir,life:.22,max:.22,type:'slash'});
 sound('slash');updateHud();}
function screenWorld(x,y){return{x:(x-cx)/scale,y:(y-cy)/scale}}
function dodge(){if(state!=='playing'||player.dead||player.dodgeCd>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+touchVec.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+touchVec.y;let len=Math.hypot(dx,dy);if(len<.1){dx=Math.cos(player.dir);dy=Math.sin(player.dir)}else{dx/=len;dy/=len}player.dodge={x:dx,y:dy,t:.22};player.dodgeCd=1.5;player.invuln=.48;player.dir=Math.atan2(dy,dx);for(let i=0;i<8;i++)spawnParticle(player.x-dx*8,player.y-dy*8,'dust');sound('dodge')}
function spawnParticle(x,y,type){particles.push({x,y,vx:(Math.random()-.5)*(type==='spark'?150:70),vy:(Math.random()-.5)*(type==='spark'?150:65),life:.25+Math.random()*.45,max:.5,size:1+Math.random()*3,type})}
function bossAttack(){let hp=boss.hp/boss.max,roll=Math.random(),type;if(roll<.25)type='melee';else if(roll<.49)type='wave';else if(roll<.74)type='mark';else if(roll<.9)type='sweep';else type='roar';let delay=type==='melee'?.95:type==='wave'?1.45:type==='mark'?1.4:type==='sweep'?1.2:1.05;
 let tx=player.x,ty=player.y;if(type==='mark'){let a=Math.random()*Math.PI*2,r=Math.random()*135;tx=player.x+Math.cos(a)*r;ty=player.y+Math.sin(a)*r;let d=Math.hypot(tx,ty);if(d>arenaR/scale-65){tx*=.7;ty*=.7}}
 boss.attack={type,t:0,delay,tx,ty,dir:Math.atan2(player.y-boss.y,player.x-boss.x),hit:false};sound(type==='roar'?'roar':'warning');}
