 function resolveBossAttack(a){if(a.hit)return;a.hit=true;let dx=player.x-a.tx,dy=player.y-a.ty,dist=Math.hypot(dx,dy);if(a.type==='melee'&&Math.hypot(player.x-boss.x,player.y-boss.y)<125)damagePlayer(28);else if(a.type==='wave'&&Math.hypot(player.x-boss.x,player.y-boss.y)<250)damagePlayer(22);else if(a.type==='mark'&&dist<55)damagePlayer(38,a.tx,a.ty);else if(a.type==='sweep'){let d=Math.hypot(player.x-boss.x,player.y-boss.y),ang=Math.atan2(player.y-boss.y,player.x-boss.x),dif=Math.atan2(Math.sin(ang-a.dir),Math.cos(ang-a.dir));if(d<205&&Math.abs(dif)<1.12)damagePlayer(32)}else if(a.type==='roar'&&Math.hypot(player.x-boss.x,player.y-boss.y)<195)damagePlayer(18);}
 function update(dt){ambientTime+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('on')}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);for(const p of embers){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0||Math.hypot(p.x,p.y)>arenaR/scale)Object.assign(p,makeEmber())}for(const p of decos){p.age+=dt}
